349	      protected readonly loading = signal(true);
350	
351	      protected readonly authorName = signal('');
352	      protected readonly score = signal<number | null>(null);
353	      protected readonly submitting = signal(false);
354	      protected readonly submitError = signal<string | null>(null);
355	      protected readonly submitSuccess = signal(false);
356	
357	      constructor() {
358	        const id = this.route.snapshot.paramMap.get('id');
359	        if (!id) {
360	          this.notFound.set(true);
361	          this.loading.set(false);
362	          return;
363	        }
364	        this.productApi.getProduct(id).subscribe({
365	          next: (product) => {
366	            this.product.set(product);
367	            this.loading.set(false);
368	          },
369	          error: () => {
370	            this.notFound.set(true);
371	            this.loading.set(false);
372	          }
373	        });
374	      }
375	
376	      protected onAuthorNameChange(value: string): void {
377	        this.authorName.set(value);
378	      }
379	
380	      protected onScoreChange(value: string): void {
381	        this.score.set(value ? Number(value) : null);
382	      }
383	
384	      protected submitRating(): void {
385	        const current = this.product();
386	        const author = this.authorName().trim();
387	        const scoreValue = this.score();
388	        if (!current || !author || scoreValue === null) {
389	          this.submitError.set('Bitte Sternewert und Namen angeben.');
390	          this.submitSuccess.set(false);
391	          return;
392	        }
393	
394	        this.submitting.set(true);
395	        this.submitError.set(null);
396	        this.submitSuccess.set(false);
397	
398	        this.productApi.submitRating(current.id, { authorName: author, score: scoreValue }).subscribe({
399	          next: (result) => {
400	            this.product.set({ ...current, averageRating: result.averageRating, ratingCount: result.ratingCount });
401	            this.submitting.set(false);
402	            this.submitSuccess.set(true);
403	            this.authorName.set('');
404	            this.score.set(null);
405	          },
406	          error: () => {
407	            this.submitting.set(false);
408	            this.submitError.set('Bewertung konnte nicht gespeichert werden. Bitte Eingaben prüfen.');
409	          }
410	        });
411	      }
412	    }
413	    ```
414	    - **`onAuthorNameChange`/`onScoreChange` als benannte Methoden statt Inline-Ausdrücke im Template:** `Number` ist als Konvertierung hier gewöhnlicher TypeScript-Code innerhalb der Komponentenklasse (kein Template-Ausdruck) — Angular-Templates lösen freistehende globale Bezeichner wie `Number` nicht auf, weswegen die Konvertierung bewusst in die Klasse verlagert ist, statt sie inline im Template zu versuchen. Identisches Muster wie das bereits etablierte „Event-Handler-Methode in der Komponente, Template ruft nur auf" (siehe `SortSelect.onChange`).
415	    - **`this.product.set({ ...current, averageRating: ..., ratingCount: ... })` statt erneutem `getProduct(id)`-Aufruf (AC 4):** Ein erneuter `GET /api/products/{id}` würde über `CatalogService.GetProductDetailAsync` (Story 2.2, AD-6) automatisch den `ViewCount` ein weiteres Mal erhöhen — ein reiner UI-Refresh der Bewertungsanzeige ist keine neue „Ansicht" des Produkts durch den Gast und sollte den Beliebtheits-Zähler nicht verfälschen. Das lokale Zusammenführen der Antwort von `submitRating` in das bestehende `product`-Signal vermeidet diesen Seiteneffekt vollständig und spart einen HTTP-Roundtrip.
416	    - **Client-seitige Minimalprüfung (`!author || scoreValue === null`) vor dem Absenden:** Verhindert unnötige Netzwerk-Roundtrips bei offensichtlich unvollständigen Eingaben; ersetzt NICHT die Server-Validierung (AC 2 bleibt Aufgabe des Backends, siehe Task 2) — beide Ebenen sind nötig, da der Server die alleinige Quelle der Wahrheit ist.
417	    - **Kein `authorName().trim()`-Trimmen vor dem Senden im DB-Vergleich relevant, hier nur zur Leerstring-Erkennung:** `AD-5`s Autorenvergleich ist exakt (kein serverseitiges Trimmen dokumentiert) — der Client trimmt nur, um zu erkennen, ob nur Leerzeichen eingegeben wurden (sonst würde `"   "` fälschlich als „ausgefüllt" durchgehen); der getrimmte Wert wird auch tatsächlich gesendet, `[ASSUMPTION: Trimmen von Autorennamen vor dem Speichern ist weder in epics.md noch in der PRD spezifiziert; führendes/nachgestelltes Leerzeichen als Teil der Autoren-Identität zu behandeln wäre kontraintuitiv und nicht durch einen AC gefordert]`.
