    const text = (fixture.nativeElement as HTMLElement).textContent ?? '';
    expect(text).toContain('Noch keine Bewertungen');
    expect(text).toContain('Lieferanten');
  });

  it('renders "Produkt nicht gefunden." on an HTTP 404 response (AC 6)', () => {
